150: static unsigned char *shine_encode_buffer_internal(shine_global_config *config,
151:                                                    int *written, int stride) {
152:   if (config->mpeg.frac_slots_per_frame) {
153:     config->mpeg.padding =
154:         (config->mpeg.slot_lag <= (config->mpeg.frac_slots_per_frame - 1.0));
155:     config->mpeg.slot_lag +=
156:         (config->mpeg.padding - config->mpeg.frac_slots_per_frame);
157:   }
158: 
159:   config->mpeg.bits_per_frame =
160:       8 * (config->mpeg.whole_slots_per_frame + config->mpeg.padding);
161:   config->mean_bits = (config->mpeg.bits_per_frame - config->sideinfo_len) /
162:                       config->mpeg.granules_per_frame;
163: 
164:   /* apply mdct to the polyphase output */
165:   shine_mdct_sub(config, stride);
166: 
167:   /* bit and noise allocation */
168:   shine_iteration_loop(config);
169: 
170:   /* write the frame to the bitstream */
171:   shine_format_bitstream(config);
172: 
173:   /* Return data. */
174:   *written = config->bs.data_position;
175:   config->bs.data_position = 0;
176: 
177:   return config->bs.data;
178: }
