180: unsigned char *shine_encode_buffer(shine_global_config *config, int16_t **data,
181:                                    int *written) {
182:   config->buffer[0] = data[0];
183:   if (config->wave.channels == 2)
184:     config->buffer[1] = data[1];
185: 
186:   return shine_encode_buffer_internal(config, written, 1);
