1: /* main.c
2:  * Command line interface.
3:  *
4:  * This fixed point version of shine is based on Gabriel Bouvigne's original
5:  * source, version 0.1.2
6:  * It was converted for use on Acorn computers running RISC OS and will require
7:  * the assembler multiply file to be replaced for other platforms.
8:  * 09/02/01 P.Everett
9:  *
10:  * Converted to a no-globals library-based system primarily for ARM-LINUX-GCC
11:  * but also works on x86 and x86_64 with the Makefile-generic, however
12:  * quality is worse right now on non-ARM as the noarch file uses bad math.
13:  * Jan 2, 2006 P.Roberts
14:  *
15:  */
16: 
17: /* Global headers. */
18: #include <stdio.h>
