204: void swap_buffer(int16_t *sample_buffer, int length) {
205:   int16_t *end = sample_buffer + length;
206: 
207:   if (length >= 2 * sizeof(long) / sizeof(int16_t)) {
208:     const unsigned long mask =
209:         (~0UL / 0xffff) * 0xff; /* 0x00ff00ff or 0x00ff00ff00ff00ff */
210:     unsigned long *long_ptr =
211:         (unsigned long *)((unsigned long)sample_buffer & -sizeof(long));
212: 
213:     /* make sample_buffer aligned on word boundary */
214:     if ((int16_t *)long_ptr != sample_buffer) {
215:       long_ptr++;
216:       do {
217:         register uint16_t tmp = *sample_buffer++;
218:         sample_buffer[-1] = bswap_16(tmp);
219:       } while (sample_buffer != (int16_t *)long_ptr);
220:     }
221: 
222:     while ((int16_t *)(long_ptr + 1) <= end) {
223:       register unsigned long tmp = *long_ptr++;
224:       long_ptr[-1] = ((tmp & mask) << 8) | ((tmp >> 8) & mask);
225:     }
226: 
227:     sample_buffer = (int16_t *)long_ptr;
228:   }
229: 
230:   while (sample_buffer < end) {
231:     register uint16_t tmp = *sample_buffer++;
232:     sample_buffer[-1] = bswap_16(tmp);
233:   }
234: }
