} wave_chunk_t;

typedef struct {
  riff_chunk_header_t header;
  uint16_t format;      /* MS PCM = 1 */
  uint16_t channels;    /* channels, mono = 1, stereo = 2 */
  uint32_t sample_rate; /* samples per second = 44100 */
  uint32_t byte_rate;   /* bytes per second = samp_rate * byte_samp = 176400 */
